from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
def read(name):return json.loads((root/name).read_text(encoding='utf-8-sig'))
def write(name,value):
 p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2),encoding='utf-8')
p=read('dist/playbook.json');ch=p['chapters'][0]
worlds=[
 ('De noodcentrale','room-dispatch','Leg het noodtransportplan vast','dispatch-plan','Zonder uitvoerbaar én verantwoord noodplan weet de chauffeur niet welke aanvragen hij eerst moet bedienen.','Het noodplan is verantwoord.','De ontvangstdocumenten in het depot laten zien welke kosten je verdeling nog niet zichtbaar maakte.'),
 ('Het ontvangstdepot','room-depot','Open de route naar de retourstroom','shared-management','De factuur, het vissersbericht en de waterafspraak beschrijven verschillende delen van hetzelfde probleem.','De kosten en de beheerafspraak zijn uit elkaar gehaald.','Volg nu de materialen naar het retour- en verwerkingsstation: daar zie je wie buiten de factuur blijft.'),
 ('Het retour- en verwerkingsstation','room-recycling','Volg het serviceticket naar de werkplaats','chain-trace','Een verzendadres vertelt nog niet waar winning, gebruik en afval terechtkomen. Je moet de route eerst reconstrueren.','De materiaalroute en de open bewijsvragen zijn zichtbaar.','Een retourticket wijst naar de reparatiewerkplaats. Daar kun je onderzoeken waarom het systeem een ander doel beloont dan je verwacht.'),
 ('De reparatiewerkplaats','chapter-1','Breng de onderbouwde pilot naar het bestuur','pilot-review','De machine beloont haar ingestelde doel. Een ingreep zonder begrip van die meetlat kan hetzelfde patroon herhalen.','De pilot heeft een bredere, toetsbare meetlat.','Wie mag die meetlat veranderen en wie ontvangt de opbrengst? Het bestuur en het eigendomsregister laten de bevoegdheden zien.'),
 ('De kamer van de spelregels','chapter-3','Volg het budget naar de etalage','control-trace','De investeringssleutel, het grootboek en de marktregels tonen verschillende bronnen van zeggenschap.','De route van eigendom naar invloed is gereconstrueerd.','Het budget gaat naar een campagne. In de etalage zie je hoe financiële doelen en ontworpen keuzeomgevingen elkaar versterken.'),
 ('De etalage van morgen','chapter-5','Open de besliskamer van les 1','integrated-case','Een nieuwe situatie vraagt om meerdere lenzen. Alleen een verkoopsignaal laat de belangen en systeemkeuzes niet volledig zien.','Je onderscheidt keuzemechanismen van de bredere spelregels.','Je gebruikt je inzichten in een nieuw stedelijk laadnetwerk, gevolgd door aanvullende vragen. Daarna begint les 2.')
]
for i,w in zip(ch['investigations'],worlds):
 name,image,label,kind,problem,unlocked,reason=w
 i['world']={'name':name,'imageKey':image,'exit':{'label':label,'lockType':kind,'problem':problem,'unlockedText':unlocked,'destinationReason':reason}}
def question(n,text,concepts,room,options):
 blocks=sorted(set(b for beat in ch['investigations'][room]['beats'] for b in beat['sourceBlocks']))
 return {'id':f'm1-q{n}','question':text,'concepts':concepts,'sourceBlocks':blocks,'options':[{'id':f'a{k}','text':o[0],'correct':o[1],'feedback':o[2]} for k,o in enumerate(options)]}
ch['knowledgeCheck']={'intro':'Gebruik de begrippen in andere situaties. Verklaar het mechanisme; de vragen vragen niet om één verplicht moreel standpunt.','items':[
 question(1,'Een zorgorganisatie heeft twee technisch haalbare roosters. Het ene beperkt wachttijd voor kwetsbare cliënten; het andere houdt alle afdelingen even lang open. Wat ontbreekt om de keuze te verantwoorden?',['schaarste','technische berekening versus normatieve afweging'],0,[('Een expliciet verdelingscriterium en de gevolgen voor de betrokken groepen.',True,'Uitvoerbaarheid begrenst mogelijkheden. Het criterium verklaart waarom je een bepaalde verdeling verdedigt.'),('Een nauwkeuriger capaciteitsberekening die de verdelingsnorm vanzelf bepaalt.',False,'Meer nauwkeurigheid kiest op zichzelf geen norm voor voorrang.'),('Eén gelijke rekeneenheid waarmee verschillende gevolgen inhoudelijk gelijk worden.',False,'Gelijke eenheden kunnen zeer verschillende behoeften en gevolgen vertegenwoordigen.')]),
 question(2,'Twee wasserijen gebruiken evenveel water en veroorzaken evenveel afval. De ene betaalt voor verwerking; de andere schuift die rekening naar de omgeving. Welke vergelijking klopt binnen deze gegevens?',['externaliteiten','prijs versus maatschappelijke kosten'],1,[('De tweede kan goedkoper lijken zonder dat de totale last voor alle betrokkenen kleiner is.',True,'De rekening ligt anders. Voor afgenomen afval of totale schade ontbreekt hier bewijs.'),('De hogere rekening van de eerste betekent dat haar maatschappelijke schade groter is.',False,'Kosten betalen en schade veroorzaken zijn verschillende zaken. De hoeveelheden blijven gelijk.'),('De lagere bedrijfsprijs van de tweede weerspiegelt dezelfde volledige kostenbasis.',False,'Een afgewentelde rekening ontbreekt juist in die bedrijfsprijs.')]),
 question(3,'Gebruikers van een gedeeld watergebied betalen hun eigen afvalrekening. Toch trekken ze samen meer water weg dan het gebied aanvult. Welke aanvulling past bij dit nieuwe probleem?',['commons','collectieve verantwoordelijkheid','begrenzing'],1,[('Afspraken over gedeeld gebruik, grenzen, toezicht en verdeling naast het betalen van kosten.',True,'Kosten internaliseren lost niet automatisch de organisatie van gedeeld gebruik op.'),('Een hogere afvalrekening zonder het gedeelde watergebruik zelf te onderzoeken.',False,'Dit verandert de kostenprikkel, maar het nieuwe bewijs gaat ook over gezamenlijke gebruiksgrenzen.'),('Een berekening van individuele opbrengsten die gezamenlijke overschrijding als gebruiksafspraak vervangt.',False,'Een opbrengstenberekening organiseert geen gezamenlijke begrenzing of beheer.')]),
 question(4,'Een verkoper toont een schoon eindproduct en één afleveradres. Welke aanvulling maakt een onderzoek naar baten, lasten en macht inhoudelijk sterker?',['grondstoffenketen','baten lasten machtsverhoudingen'],2,[('Verbind winning, verwerking, gebruik en afval aan betrokken partijen, belangen en ontbrekende gegevens.',True,'De keten is zowel een materiële route als een verdeling van gevolgen en invloed.'),('Beperk de analyse tot het afleveradres omdat daar het eigendom officieel overgaat.',False,'Een eigendomsoverdracht wist gevolgen in eerdere en latere schakels niet uit.'),('Gebruik dezelfde verkoopprijs als maat voor de lasten van alle partijen in de keten.',False,'Die prijs toont niet automatisch lonen, afval, afhankelijkheden en afgewentelde kosten.')]),
 question(5,'Medewerkers willen langer repareren. Hun score en budget worden echter lager zodra reparaties de nieuwverkoop vertragen. Welke verklaring verdient onderzoek?',['Goodpaster','KPI-prikkels','systeeminterventie'],3,[('Onderzoek hoe meetlat, beloning en bevoegdheid individuele zorg beperken en hoe een ingreep daarop werkt.',True,'De persoonlijke afweging en het organisatieontwerp kunnen elkaar tegenwerken. Dat vraagt concrete systeeminformatie.'),('Leid uit de lagere reparatiescore af dat de medewerkers hun zorg niet serieus nemen.',False,'De score meet een organisatorisch gekozen doel. Zij bewijst geen persoonlijke bedoeling.'),('Neem een nieuwe zorgverklaring als voldoende verandering zolang de bestaande beloning blijft gelden.',False,'Andere woorden veranderen de meetlat en de gevolgen niet vanzelf.')]),
 question(6,'Een rapport laat gemiddeld rendement boven economische groei zien. Wat kun je daarmee binnen Piketty’s lens zorgvuldig onderzoeken?',['Piketty','r groter dan g','vermogensconcentratie afhankelijk van context'],4,[('Een mogelijke route naar vermogensconcentratie, mede afhankelijk van verdeling, erfenissen, belasting en instituties.',True,'r > g is een relevante verhouding, geen contextloze voorspelling van iedere individuele uitkomst.'),('Een onvermijdelijkzelfde vermogenspad voor alle huishoudens, ongeacht bezit en instituties.',False,'Bezitsverdeling, instituties en huishoudelijke omstandigheden beïnvloeden die route.'),('Een gelijkwaardige verdeling van invloed omdat beide grootheden in percentages staan.',False,'De meeteenheid zegt niets over de verdeling van bezit en zeggenschap.')]),
 question(7,'Een platform bezit klantgegevens, groeit door schaalvoordelen en bepaalt zichtbaarheid. Welke vergelijking onderscheidt eigendom, bijdrage en invloed?',['databezit','schaalvoordelen','eigendom versus bijdrage','data-autonomie'],4,[('Onderzoek wie data en toegang controleert, wie waarde bijdraagt en welke regels hun opbrengst en invloed verbinden.',True,'Een bijdrage en een eigendomsrecht zijn niet hetzelfde. De institutionele koppeling verdient onderzoek.'),('Gebruik bezit als volledige maat voor hoeveel iedere betrokken partij heeft bijgedragen.',False,'Gebruikers, medewerkers en publieke infrastructuur kunnen waarde leveren zonder dezelfde eigendomsrechten.'),('Behandel de huidige toegangstarieven als bewijs dat gebruikers gelijkwaardige beslisrechten hebben.',False,'Een tarief of toegang zegt niet automatisch wie de spelregels kan veranderen.')]),
 question(8,'Een winkel benadrukt zowel een populaire keuze als een voordeel dat morgen vervalt. Veel bezoekers volgen die optie. Welke analyse houdt de mechanismen uit elkaar?',['kuddegedrag','verliesaversie','geconstrueerde keuzeruimte'],5,[('Onderzoek de meerderheid als informatie, mogelijke verliesdruk en hoe de zichtbaarheid van alternatieven is ontworpen.',True,'Meerdere mechanismen kunnen samen optreden. Je hebt onderscheidend bewijs nodig voor hun precieze aandeel.'),('Gebruik de verkooppiek om aan te tonen dat iedere bezoeker uitsluitend de meerderheid volgde.',False,'Eén einduitkomst scheidt de mogelijke mechanismen niet.'),('Beschouw beschikbare alternatieven als voldoende bewijs dat presentatie en aandacht geen invloed hadden.',False,'Een formeel beschikbare optie kan minder zichtbaar of anders geframed zijn.')])
]}
write('dist/playbook.json',p)
original=read('dist/npc-dialogues.json');rooms=[]
secondary=[
 ('Eva','Continuïteit en bestuurlijke keuzes','Ik bewaak ook de continuïteit. Vraag mij welk belang een productieplan dient, en welke keuze het plan nog niet kan rechtvaardigen.',[
  ('Waarom telt de lancering ook mee?','Productie kan inkomsten en werk ondersteunen. Dat is een relevant belang. Het zegt nog niet hoeveel bescherming noodklanten moeten krijgen. Die keuze vraagt een expliciet criterium.', ['Een korte vertraging kan omzet kosten. Een langer tekort kan noodzakelijke communicatie raken. Vergelijk de concrete gevolgen voordat je één belang dominant maakt.','Een spreadsheet kan opbrengst en capaciteit berekenen. De gewichten die je aan gezondheid, werk of continuïteit geeft, vragen daarnaast om een verantwoording.','Niet elk productiebelang is egoïstisch en niet elke noodclaim is onderbouwd. Onderzoek behoeften en gevolgen; vermijd het oordeel alleen uit het label van een afdeling.']),
  ('Zijn de spelregels al gegeven?','We werken binnen bestaande afspraken. Maar die afspraken zijn ooit gekozen. Je kunt onderzoeken wie bescherming krijgt, wie risico draagt en wie de regels kan aanpassen.', ['Friedmans positie koppelt winststreven aan handelen binnen de spelregels. De vervolgvraag is wat die regels beschermen en welke ruimte voor misleiding of afwenteling zij beperken.','Een bestaande regel kan voorspelbaarheid geven en tegelijk een belang onvoldoende beschermen. Geldigheid en inhoudelijke rechtvaardiging zijn verschillende vragen.','Dit experiment beweert niet dat elke regel onrechtvaardig is. Het maakt zichtbaar dat regels keuzes over toegang, risico en bescherming bevatten.'])]),
 ('Mila','Technisch onderhoud en materiaalverwerking','De factuur vertelt wat wij betalen. Ik kan je ook laten zien welk materiaal of afval buiten die factuur terechtkomt.',[
  ('Betalen en voorkomen zijn hetzelfde?','Nee. Een rekening betalen verdeelt de kosten. Minder vervuilen verandert de fysieke gevolgen. Beide kunnen nodig zijn; controleer welke handeling jouw bewijs werkelijk laat zien.', ['In de proef blijft de hoeveelheid afval gelijk. Alleen het betaalde aandeel verschuift. Een lagere afvalhoeveelheid zou een aparte verandering en meting vragen.','Een prijs kan een prikkel geven om afval te beperken. Het bestaan van die prikkel bewijst nog niet dat het volume in deze concrete vergelijking al veranderd is.','Onze eenvoudige kostentabel is geen volledige schadeberekening. Gezondheid, ecosystemen en langdurige gevolgen kunnen meer gegevens vereisen.']),
  ('Waarom ook over gezamenlijk beheer praten?','Een gedeelde bron vraagt afspraken tussen gebruikers. Zelfs als iedereen een rekening betaalt, kun je samen een gebruiksgrens overschrijden. Beheer en kosten volgen daarom verschillende vragen.', ['Vraag wie toegang heeft, welke grens geldt, wie meet en wie kan corrigeren. Een afspraak moet aansluiten op het daadwerkelijke gedeelde gebruik.','De factuur volgt geld. De rivierafspraak volgt toegang en gebruik. Leg ze naast elkaar in plaats van één lens als vervanging van de andere te gebruiken.','Er is geen universele beheervorm die hier vanzelf het beste is. De omstandigheden, deelname, toezicht en gevolgen moeten de gekozen afspraken ondersteunen.'])]),
 ('Omar','Ontvangst en logistieke routes','Ik weet waar een zending binnenkomt. Dat is nog niet hetzelfde als weten waar grondstoffen vandaan komen of waar afval eindigt.',[
  ('Waarom is een adres niet genoeg?','Een adres beschrijft één overdracht. De grondstoffenroute en de afvalroute lopen verder. Wie daar risico of afhankelijkheid ervaart, kan buiten het ontvangstregister blijven.', ['Volg winning, verwerking, gebruik en afval afzonderlijk. Kijk vervolgens wie opbrengst krijgt, wie lasten draagt en wie voorwaarden kan stellen.','Een technisch perfect traceernummer kan nog steeds alleen transport tonen. Controleer welke informatie het systeem heeft vastgelegd en wat ontbreekt.','Een landnaam alleen bewijst geen individuele arbeidsomstandigheid. Algemene ketenrisico’s en concrete leveranciersclaims vragen verschillende soorten bewijs.']),
  ('Hoe ontdek ik invloed in de keten?','Vraag wie toegang tot grondstoffen, infrastructuur, gegevens of afzet controleert. Die afhankelijkheden kunnen onderhandelingsruimte geven. Maak ook zichtbaar waar je nog geen gegevens over hebt.', ['Een leverancier die moeilijk vervangbaar is, kan voorwaarden stellen. Een afnemer met veel alternatieven kan andere ruimte hebben. Onderzoek de werkelijke relatie.','De routekaart verbindt plaatsen én partijen. Een pijl hoort niet alleen een pakket, maar ook een afhankelijkheid of een verschoven last te verklaren.','Afhankelijkheid betekent niet automatisch misbruik. Voor een oordeel over afspraken heb je voorwaarden, alternatieven en gevolgen nodig.'])]),
 ('Mila','Onderhoud en reparatie','Ik kan de machine bedienen. Iris onderzoekt de meetlat. Samen kunnen we zien wanneer een technisch geslaagde uitvoering toch belangrijke belangen mist.',[
  ('Kan een werkende machine toch iets missen?','Ja. Zij kan het ingestelde doel goed uitvoeren terwijl bijvoorbeeld reparatiebaarheid niet wordt meegerekend. Het technische succes en de volledigheid van de meetlat zijn verschillende beoordelingen.', ['Een groen lampje betekent hier dat de test is afgerond. Kijk welke variabelen zijn getest voordat je daar een bredere conclusie aan verbindt.','Voeg niet alleen een nieuw woord toe. Leg vast welk belang anders wordt meegewogen en welke gevolgen je daarna daadwerkelijk controleert.','Een bredere meetlat maakt niet elk conflict weg. Sommige doelen botsen ook na een betere meting; dan blijft een verantwoorde afweging nodig.']),
  ('Waarom kan een medewerker het niet alleen oplossen?','Een medewerker kan een moreel bezwaar zien en toch weinig ruimte hebben als budget, beloning en bevoegdheden een andere richting sturen. Onderzoek persoon en ontwerp samen.', ['Een reparateur kan klanten willen helpen terwijl de score alleen nieuwverkoop beloont. Een betere intentie verandert die beloning niet vanzelf.','Goodpasters paradox laat de spanning tussen individuele morele zorg en economisch ingerichte organisatie zien. Zij is geen vrijbrief om iedere persoonlijke verantwoordelijkheid te laten verdwijnen.','Een pilot moet laten zien wat er verandert. Een nieuwe regel zonder uitvoering, middelen of feedback kan hetzelfde patroon blijven produceren.'])]),
 ('Noor','Analyse van eigendom en systeemregels','Het grootboek toont bezit en opbrengst. Ik help je de stap naar zeggenschap onderzoeken zonder cijfers als een complete morele verklaring te behandelen.',[
  ('Bewijst rendement automatisch zeggenschap?','Het kan een bron van middelen zijn, maar de precieze beslisrechten volgen ook uit eigendomsrechten en instituties. Leg de cijfers naast de regels voor bestuur en toegang.', ['Onderzoek wie stemrechten heeft, wie budget kan stoppen en wie informatie krijgt. Opbrengst en besluitmacht kunnen verbonden zijn zonder dezelfde grootheid te zijn.','Eigendom kan autonomie ondersteunen, zoals in Smiths lens. Geconcentreerd bezit kan ook afhankelijkheden scheppen. De cursus vraagt beide routes te onderzoeken.','Een gemiddelde rendementsverhouding vertelt niet hoe iedere partij wordt geraakt. Bezitsverdeling, belasting, erfenissen en andere instituties kunnen de uitkomst beïnvloeden.']),
  ('Zijn markt en staat vaste tegenpolen?','Markten werken binnen regels voor bezit, contracten, toezicht en toegang. Publieke en private keuzes vormen daarom samen de speelruimte; hun precieze effecten vragen context en bewijs.', ['Privatisering verandert wie bezit of beheer krijgt. Deregulering verandert regels. Financialisering geeft financiële maatstaven meer gewicht. Het zijn verwante maar verschillende veranderingen.','Vraag bij een publieke voorziening wie toegang krijgt, wie financiert en wie kan corrigeren. De naam van de eigenaar beoordeelt niet alle concrete gevolgen.','Dezelfde term kan verschillende uitvoeringen omvatten. Vergelijk bestaande en voorgestelde regels voordat je één algemeen label als oorzaak aanwijst.'])]),
 ('Iris','Keuzeomgeving en ethische analyse','Lena maakt de campagne. Ik onderzoek hoe die aandacht, onzekerheid en mogelijke verliezen organiseert. Een verkooppiek vertelt nog niet welk mechanisme doorslaggevend was.',[
  ('Hoe onderscheid ik de mechanismen?','Kuddegedrag gebruikt anderen als informatie of houvast. Verliesaversie geeft mogelijke verliezen extra gewicht. De ontworpen keuzeomgeving bepaalt welke signalen en opties opvallen.', ['Een populair label en een verdwijnend voordeel kunnen tegelijk werken. Varieer één onderdeel en vergelijk, in plaats van de verkooppiek als bewijs voor één oorzaak te nemen.','Meerderheidskeuzes kunnen zichzelf versterken: meer zichtbaarheid geeft meer navolging. Dat zegt nog niet dat iedereen dezelfde reden had.','Niet elke gevolgde keuze is onredelijk. Soms hebben anderen relevante informatie. Het onderzoek vraagt wanneer navolging helpt en wanneer zij tunnelvisie of instabiliteit versterkt.']),
  ('Waarom de bedrijfslogica erbij betrekken?','Kortetermijnrendement kan bepalen welke campagne en investering voorrang krijgt. Een stakeholderlens vraagt ook naar werknemers, onderhoud, duurzaamheid en weerbaarheid. Dat is breder dan één consumententruc.', ['Een financiële keuze kan belangen ondersteunen en tegelijk andere lasten minder zichtbaar maken. Onderzoek hoe de meetlat en het budget dat patroon vormgeven.','Dezelfde aankoop kan individueel logisch voelen en collectief een kwetsbaar patroon versterken. Verbind de concrete keuze aan de bredere regels en prikkels.','Een stakeholderlabel bewijst nog geen betere uitkomst. Laat zien welke belangen, besluitrechten en gevolgen daadwerkelijk anders worden behandeld.'])])
]
for index,row in enumerate(original['rooms']):
 primary=row['npc'];name,role,opening,topics=secondary[index];newtopics=[]
 for k,(q,answer,followups) in enumerate(topics):newtopics.append({'id':f'second-{k}','question':q,'answer':answer,'followups':[{'id':f'deeper-{j}','question':['Kun je een voorbeeld geven?','Hoe hangt dit met de theorie samen?','Waar ligt de grens van deze uitleg?'][j],'answer':text} for j,text in enumerate(followups)]})
 # Extra layer adds real explanatory depth to the primary voice as well.
 for t in primary['topics']:
  if len(t['followups'])<3:t['followups'].append({'id':'world-evidence','question':'Hoe onderzoek ik dit in de kamer?','answer':max(ch['investigations'][index]['beats'],key=lambda b:len(set(t.get('concepts',[])) & set(b['concepts'])))['hint']})
 rooms.append({'investigationId':row['investigationId'],'npcs':[primary,{'name':name,'role':role,'opening':opening,'topics':newtopics}]})
write('dist/chapters/m1-npcs.json',{'schemaVersion':2,'rooms':rooms})
print('Six logically connected first-lesson locations, deeper paired NPCs and eight additional knowledge questions authored.')
